package dev.pickspot.app.probe

import android.app.Activity
import android.app.Instrumentation
import android.content.pm.ApplicationInfo
import android.os.Build
import android.os.Bundle
import dev.pickspot.app.domain.*
import dev.pickspot.app.routing.*
import org.json.JSONArray
import org.json.JSONObject

/** Offline wire contract check against a report generated by the server's fixed fixture. */
class LiveRouteContractProbe(private val instrumentation:Instrumentation){
    fun execute(){
        val report=JSONObject();var checks=0
        fun verify(value:Boolean){check(value);checks++}
        fun rejected(block:()->Unit){var failed=false;try{block()}catch(_:Exception){failed=true};verify(failed)}
        try{
            check(Build.HARDWARE in listOf("ranchu","goldfish")&&instrumentation.targetContext.applicationInfo.flags and ApplicationInfo.FLAG_DEBUGGABLE!=0)
            val fixture=JSONObject(instrumentation.context.assets.open("live-route-contract.json").bufferedReader().use{it.readText()})
            val at=fixture.getLong("at");val wire=fixture.getJSONObject("request")
            fun point(json:JSONObject)=GeoPoint(json.getDouble("latitude"),json.getDouble("longitude"))
            val route=VehicleRoute(VehiclePlace(point(wire.getJSONObject("destination").getJSONObject("point")),"검사 목적지"),emptyList(),"PLEOS_UNMAPPED",at)
            val draft=PreparedVehicleTrip(MeasuredVehicleFix(point(wire.getJSONObject("driver").getJSONObject("point")),at,12f,at,100_000,0),route,DrivePreference.RECOMMENDED,at+30000)
            val rawSession=fixture.getJSONObject("session");val id=rawSession.getString("id")
            val session=LiveRouteJson.session(rawSession,id)
            val request=LiveRouteRequest(draft,session.version,session.passengerRevision,listOf("a","b","c"))
            verify(session.ready(at))
            fun normalized(value:Any?):Any?=when(value){
                is JSONObject->value.keys().asSequence().toList().sorted().associateWith{normalized(value.get(it))}
                is JSONArray->(0 until value.length()).map{normalized(value.get(it))}
                is Number->value.toDouble();else->value
            }
            val encoded=JSONObject(LiveRouteJson.encode(request))
            verify(normalized(encoded)==normalized(wire))
            verify(!encoded.has("passenger")&&!encoded.has("passengerRevision")&&!encoded.has("routeOption")&&!encoded.has("appKey"))
            val parsed=LiveRouteJson.report(fixture.getJSONObject("report"),request)
            verify(parsed.candidates.map{it.detourSeconds}==listOf(120,300,45))
            verify(parsed.candidates.all{it.evidence.conditions=="실제 장소가 아닌 검사 자료"&&it.evidence.sources==listOf("https://example.test/catalog")})
            verify(parsed.validUntil==at+30000&&parsed.sessionVersion==session.version+1)
            fun malformed(edit:(JSONObject)->Unit){rejected{val json=JSONObject(fixture.getJSONObject("report").toString());edit(json);LiveRouteJson.report(json,request)}}
            malformed{it.put("synthetic",true)}
            malformed{it.put("referenceOnly",false)}
            malformed{it.put("vehicleRouteOptionMatched",true)}
            malformed{it.put("sessionVersion",session.version)}
            malformed{it.put("passengerRevision",session.passengerRevision+1)}
            malformed{it.put("drivePreference","free-first")}
            malformed{it.put("inputValidUntil",at+60000)}
            malformed{it.getJSONArray("candidates").getJSONObject(0).put("walkMeters","230")}
            malformed{it.getJSONArray("candidates").getJSONObject(0).put("walkSeconds",-1)}
            malformed{it.getJSONArray("candidates").getJSONObject(1).put("id","a")}
            malformed{it.getJSONArray("candidateProvenance").getJSONObject(0).getJSONObject("review").put("status","pending")}
            malformed{it.getJSONArray("candidateProvenance").getJSONObject(0).getJSONArray("sources").getJSONObject(0).put("url","http://example.test")}
            malformed{it.put("candidates",JSONArray())}
            rejected{LiveRouteJson.session(rawSession,"other-session")}
            rejected{LiveRouteJson.session(JSONObject(rawSession.toString()).put("isDemo",true),id)}
            for(origin in listOf("http://localhost","https://example.test/","https://user@example.test","https://example.test?token=x","https://example.test#x"))
                rejected{HttpsLiveRouteGateway(origin,id,"a".repeat(43))}
            val gateway=HttpsLiveRouteGateway("https://example.test",id,"a".repeat(43))
            verify(!gateway.toString().contains(id)&&!gateway.toString().contains("a".repeat(43)))
            checks+=LiveRouteTransportChecks.run(fixture,request)
            report.put("passed",true)
        }catch(e:Exception){report.put("passed",false).put("failure",e.javaClass.simpleName)}
        report.put("checks",checks).put("networkRequests",0).put("locationReads",0).put("navigationRequests",0)
        instrumentation.finish(Activity.RESULT_OK,Bundle().apply{putString("stream",report.toString(2)+"\n")})
    }
}
